def is_path_possible(n, m, q, grid, moves, strings):
    visited = set()
    def dfs(x, y, s):
        if (x, y) in visited:
            return False
        visited.add((x, y))
        grid[y][x] = s[-1]
        for a, b in moves:
            nx, ny = x + a, y + b
            if (0 <= nx < n) and (0 <= ny < m):
                if dfs(nx, ny, (s[-1] + grid[ny][nx]) % 10):
                    return True
        return False
    for s in strings:
        q = deque(s)
        paths = set()
        q[-1] = 10
        while True:
            new_q = [q[3]]
            for _ in range(3):
                d = q.popleft()
                for a, b in moves:
                    nx, ny = d + a, d + b
                    if (0 <= nx < n) and (0 <= ny < m):
                        new_q.append((new_q[0] * 10 + grid[ny][nx]) % 10)
            if dfs(0, 0, tuple(new_q)):
                paths.add(tuple(q))
            if q == [0, 0] or q == [1, 1]:
                break
        s_str = ''.join([str(d) for d in q])
        paths.append((s_str, x, y))
    return {'YES': '', 'NO': 'YES' if s_str in visited else 'NO' for _, s_str, x, y in paths}

