def increment_number(number):
    reversed_number = [int(r) for r in str(number)[::-1]] + [0]
    carry = 1

    for i in range(len(reversed_number)):
        if carry == 0:
            break

        if reversed_number[i] == 9:
            reversed_number[i] = 0
            if i + 1 >= len(reversed_number):
                reversed_number += [1]
                break

            else:
                reversed_number[i + 1] += 1
                carry = 0
                continue
        else:
            reversed_number[i] += 1
            carry = 0
            continue

    return int(''.join([str(d) for d in reversed_number][::-1]))

def perform_steps(n, digits_str):
    numbers = [convert_to_numbers(n, digits_str)]
    for _ in range(3):
        new_number = increment_number(numbers[-1])
        numbers.append(new_number)
    return numbers

