def is_divisible_by_n(n, elements):
    subset_sum = 0
    subset_size = 0
    last_index = -1
    for i in range(len(elements)):
        if subset_sum % n == 0 and last_index == i:
            return None
        if subset_sum > elements[i]:
            return None
        if subset_sum + elements[i] >= n * subset_size:
            subset_size += 1
            subset_sum = elements[i]
        subset_sum += elements[i]
        last_index = i
    if subset_sum % n == 0 and last_index == len(elements) - 1:
        return subset_size
    else:
        return None

def get_indices(subset_size, elements, start_index):
    indices = []
    for i in range(start_index, len(elements) + 1, subset_size):
        for j in range(start_index, i - subset_size, -1):
            indices.append(j)
    return indices

