import re

def parse_sort_rules(rules_str):
    sort_rules = {}
    for rule in rules_str.split(', '):
        field_name, order = rule.split('=')
        sort_rules[field_name] = order
    return sort_rules

def csv_to_table(input_data):
    rows = input_data.split('\n')
    headers = rows[0].strip().split()
    table_data = [row.strip().split() for row in rows[1:] if row.strip()]
    return headers, table_data

def sort_table(table_data, sort_rules):
    for field, order in sort_rules.items():
        if order.lower() == 'asc':
            table_data.sort(key=lambda row: tuple(row[field] if field in row else '' for row in table_data))
        elif order.lower() == 'desc':
            table_data.sort(key=lambda row: tuple(row[field] if field in row else '' for row in table_data), reverse=True)
    return table_data

