from typing import List
from itertools import product

def find_dp(idx: int, q: int, dp: List[List[int]]) -> int:
    if idx == len(q):
        return 1
    if dp[idx][q] != -1:
        return dp[idx][q]
    dp[idx][q] = 0
    for k in range(min(q, 2), 0, -1):
        res = (k ** (q - k)) * find_dp(idx + 1, q - k, dp)
        dp[idx][q] += res
        dp[idx][q] %= 490019
    return dp[idx][q]

def compute_carry_product(n: int, a: List[int], m: int, b: List[int], word_size: int) -> int:
    dp = [[-1 for _ in range(n)] for _ in range(m)]
    dp.append([0 for _ in range(n)])
    prod = 1
    for i in range(1, n + 1):
        if i % 2 == 0:
            for q in product({0}, range(word_size + n)):
                res = find_dp(0, q, dp)
                if res > 0:
                    prod += res
                    prod %= 490019
        else:
            for q in product({1}, range(word_size + n)):
                res = find_dp(0, q, dp)
                if res > 0:
                    prod += res
                    prod %= 490019
    return prod

