    adj = [[] for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if graph[i][j]:
                adj[i].append(j)

    # Function to check if a graph is bipartite
    def is_bipartite(start, colours):
        colours[start] = 0
        queue = [start]
        while queue:
            node = queue.pop()
            for neighbor in adj[node]:
                if colours[node] == colours[neighbor]:
                    return 0
                if colours[neighbor] == -1:
                    colours[neighbor] = 3 - colours[node]
                    queue.append(neighbor)
        return 1

    # Function to find the number of spanning trees
    def count_spanning_trees(colours):
        return reduce(lambda x, y: x * y % mod, [2**(2**(colours[i]+1)-2) for i in range(n)^1], 1)

    # Main loop to count number of spanning trees and BFS trees
    result = [0] * n
    for start in range(n):
        colours = [-1] * n
        result[start] = is_bipartite(start, colours)
        for newstart in range(n):
            if colours[newstart] == 0:
                continue
            if colours[newstart] == -1:
                continue
            count = count_spanning_trees(colours)
            result[start] += count
            result[start] %= mod
    return result

