from collections import deque

MOD = 998244353

class OddSum:
    def __init__(self, N):
        self.N = N
        self.dp = [0] * (2 * N + 1)
        self.q = deque()

    def add(self, value, index):
        value %= MOD
        self.q.append((value, index))

    def get_sum(self, i):
        while self.q and self.q[0][1] < i:
            _, j = self.q.popleft()
            self.q.append((j, self.N + 1))
        self.q.append((abs(self.q[0][0] - 1) % MOD, self.N + 1))

    def query(self):
        sum_ = 0
        for i in range(min(2 * self.N + 1, 1) // 2, max(0, self.N), -1):
            _, i = tuple(self.q.popleft())
            if self.q:
                sum_ += 2 * (i + 2 * MOD - sum_(MOD - sum_) % MOD) * self.dp[i] % MOD

        return sum_ % MOD

