import math

def calculate_area(x1, y1, x2, y2):
    return abs(x1 * y2 + x2 * y1) / 2

def find_centroid(vertices):
    x, y = 0.0, 0.0
    for vertex in vertices:
        x += vertex[0]
        y += vertex[1]
    return x / len(vertices), y / len(vertices)

def solve_kuzu_polygon(vertices):
    n = len(vertices)
    total_area = 0.0
    num_squares = 0
    for i in range(n):
        for j in range(i + 1, n):
            area = calculate_area(*vertices[i], *vertices[j])
            total_area += area
            num_squares += 1
    expected_area = total_area / num_squares
    return expected_area

def main():
    n = int(input())
    vertices = []
    for _ in range(n):
        x, y = map(int, input().split())
        vertices.append((x, y))
    expected_area = solve_kuzu_polygon(vertices)
    print(expected_area)

if __name__ == "__main__":
    main()
